/**
 * Supertrader 7.0 – versioned corporate-action overlay of the research dataset (V4-D1 resolution, owner decision E1).
 *
 * The overlay is a RESEARCH-DATASET TRANSFORM on the frozen snapshot, never a write to quant/data or to the snapshot:
 *  - its manifest is GENERATED by the run (run-sf7-ca-resolution.mjs) from the CONFIRMED_UNDECLARED_SPLIT sessions of
 *    integrity/ca-resolution.mjs – one entry { segmentId, date, splitFactor, label, evidenceSha256 } per session – sorted,
 *    canonically serialised and hashed (manifestSha256); nothing in it is written by hand;
 *  - applying it sets the provider field splitFactor of the raw snapshot bar of that session (Tiingo semantics: new
 *    shares per old share, 1:10 reverse = 0.1) where the provider carried 1, and nothing else. The research bars are then
 *    rebuilt by the UNCHANGED production path (runner/snapshot-input.mjs -> validation/lib.mjs#adjustSeries, the snapshot
 *    convention of ADR-002, the same divisor semantics as quant/engines/return-series.js#splitFactors): prices before the
 *    session are divided by the cumulative factor, volumes multiplied, raw close / raw volume stay the provider values.
 *    There is no second price derivation: a corrected split is indistinguishable from a split the provider had declared;
 *  - back-adjusting a later-discovered split onto earlier bars is standard back-adjustment (every declared split of the
 *    snapshot already does this). It rescales the earlier ADJUSTED levels by one constant; relatives, raw-price rules
 *    (raw close floor, raw dollar volume) and every causal indicator ratio before the session are unchanged. The trading
 *    decision path reads adjusted bars only, exactly as for declared splits, so no information about the session leaks
 *    into a decision before it beyond what every back-adjusted series carries.
 * Quarantine of UNRESOLVED sessions: quarantineAtSessions cuts exactly like integrity/discontinuity.mjs#quarantineSecurity
 * (BOOK semantics, MIN_SEGMENT_BARS, id '#dq<n>', terminal handling) but only at the given sessions, so a confirmed
 * genuine move stays uncut and a corrected split no longer exists as a jump.
 */
import crypto from 'node:crypto';
import { securityFromSegment } from '../runner/snapshot-input.mjs';
import { MIN_SEGMENT_BARS, DQ_VERSION, flagDiscontinuities } from './discontinuity.mjs';

export const CA_OVERLAY_VERSION = 'sf7-ca-overlay-1.0.0';
const sha = (x) => crypto.createHash('sha256').update(typeof x === 'string' ? x : JSON.stringify(x)).digest('hex');

/** Canonical overlay manifest from classified sessions (only CONFIRMED_UNDECLARED_SPLIT entries are taken). */
export function buildOverlayManifest(classified, { snapshotId = null, classifierVersion = null, evidenceInputs = {} } = {}) {
  const entries = classified.filter((c) => c.cls === 'CONFIRMED_UNDECLARED_SPLIT').map((c) => {
    if (!(c.splitFactor > 0) || c.splitFactor === 1 || typeof c.segmentId !== 'string' || typeof c.date !== 'string') throw new Error('CA_OVERLAY_ENTRY_INVALID');
    return { segmentId: c.segmentId, date: c.date, splitFactor: c.splitFactor, label: c.label, evidenceSha256: sha(c.evidence) };
  }).sort((a, b) => (a.segmentId === b.segmentId ? a.date.localeCompare(b.date) : a.segmentId.localeCompare(b.segmentId)));
  const seen = new Set();
  for (const e of entries) { const k = `${e.segmentId}|${e.date}`; if (seen.has(k)) throw new Error('CA_OVERLAY_DUPLICATE'); seen.add(k); }
  const body = { schema: 'supertrader-ca-overlay-manifest-1.0.0', version: CA_OVERLAY_VERSION, snapshotId, classifierVersion, evidenceInputs, entries };
  return { ...body, manifestSha256: sha(body) };
}

/** Verifies the manifest hash (a hand edit breaks it). */
export function verifyOverlayManifest(m) {
  const { manifestSha256, ...body } = m;
  return manifestSha256 === sha(body);
}

/**
 * Applies the overlay to raw snapshot segments: returns a Map segmentId -> patched segment (a shallow copy whose raw
 * bars are copies; only splitFactor of the overlay sessions differs). Fails closed when a session is missing or the
 * provider already carries a factor there.
 */
export function applyOverlayToSegments(segs, manifest) {
  if (!verifyOverlayManifest(manifest)) throw new Error('CA_OVERLAY_MANIFEST_HASH_MISMATCH');
  const byId = new Map(segs.map((s) => [s.id, s])), out = new Map();
  for (const e of manifest.entries) {
    const src = out.get(e.segmentId) || byId.get(e.segmentId);
    if (!src) throw new Error('CA_OVERLAY_SEGMENT_MISSING');
    const raw = out.has(e.segmentId) ? src.raw : src.raw.map((b) => ({ ...b }));
    const k = raw.findIndex((b) => b.date === e.date);
    if (k < 1) throw new Error('CA_OVERLAY_SESSION_MISSING');
    if (Number.isFinite(raw[k].splitFactor) && raw[k].splitFactor !== 1) throw new Error('CA_OVERLAY_SESSION_ALREADY_DECLARED');
    raw[k].splitFactor = e.splitFactor;
    out.set(e.segmentId, { ...src, raw, caOverlay: [...(src.caOverlay || []), { date: e.date, splitFactor: e.splitFactor, version: CA_OVERLAY_VERSION }] });
  }
  return out;
}

/**
 * Research dataset with the overlay: every security keeps its object unless its segment is patched; a patched one is
 * rebuilt from the patched raw bars by the production path and keeps the attached fundamentals (fund).
 */
export function correctedDataset(ds, segs, manifest) {
  const patched = applyOverlayToSegments(segs, manifest);
  const securities = ds.securities.map((s) => {
    const p = patched.get(s.id); if (!p) return s;
    const x = securityFromSegment(p);
    if (s.fund !== undefined) x.fund = s.fund;
    x.caOverlay = p.caOverlay;
    return x;
  });
  return { ds: { ...ds, securities }, patchedSegments: patched.size };
}

/**
 * Cuts one research security at the given bar indices with the semantics of discontinuity.mjs#quarantineSecurity under
 * a BOOK policy (the flagged bar closes the earlier piece and opens the next). Identical pieces to quarantineSecurity
 * when idx are all K-flags (tested); policy is only a label here.
 */
export function quarantineAtSessions(sec, idx, policy) {
  const flags = [...new Set(idx)].filter((i) => i >= 1 && i < sec.bars.length).sort((a, b) => a - b);
  if (!flags.length) return { pieces: [sec], droppedBars: 0 };
  const starts = [0, ...flags], n = sec.bars.length, raw = [];
  for (let p = 0; p < starts.length; p++) {
    const end = p + 1 < starts.length ? (policy.settle === 'BOOK' ? starts[p + 1] : starts[p + 1] - 1) : n - 1;
    raw.push({ p, bars: sec.bars.slice(starts[p], end + 1), final: p === starts.length - 1 });
  }
  const kept = raw.filter((x) => x.bars.length >= MIN_SEGMENT_BARS);
  const dropped = raw.filter((x) => x.bars.length < MIN_SEGMENT_BARS).reduce((a, x) => a + x.bars.length, 0);
  const pieces = kept.map((x, j) => {
    const last = j === kept.length - 1, lastDate = x.bars.at(-1).date;
    const terminal = last ? (sec.terminal ? { ...sec.terminal, date: lastDate } : null) : { date: lastDate, cause: 'DATA_GAP', distress: false, delistClass: null };
    return { ...sec, id: x.p === 0 ? sec.id : `${sec.id}#dq${x.p}`, bars: x.bars, terminal, dataQuarantine: { policy: policy.id, version: DQ_VERSION, overlay: CA_OVERLAY_VERSION, piece: x.p, of: raw.length, endsAtFlag: !x.final, keptOriginalTerminal: last } };
  });
  return { pieces, droppedBars: dropped };
}

/**
 * Quarantine of the UNRESOLVED sessions on a (corrected) dataset: datesBySegment maps a security id to the dates to
 * cut at. Every cut date must still be a flagged session of the corrected series at level k (fail closed otherwise).
 */
export function quarantineUnresolved(ds, datesBySegment, policy) {
  const out = []; let cuts = 0, dropped = 0;
  for (const s of ds.securities) {
    const dates = datesBySegment.get(s.id);
    if (!dates?.length) { out.push(s); continue; }
    const idx = dates.map((d) => s.bars.findIndex((b) => b.date === d));
    if (idx.some((i) => i < 1)) throw new Error('CA_QUARANTINE_SESSION_MISSING');
    const still = new Set(flagDiscontinuities(s.bars, policy.k));
    if (idx.some((i) => !still.has(i))) throw new Error('CA_QUARANTINE_SESSION_NOT_FLAGGED');
    const q = quarantineAtSessions(s, idx, policy); out.push(...q.pieces); cuts += idx.length; dropped += q.droppedBars;
  }
  return { ds: { ...ds, securities: out }, cuts, droppedBars: dropped };
}
